!********************************************************************************
!********************************************************************************
!********************************************************************************
! NACA00XX functions
!********************************************************************************
!********************************************************************************
!********************************************************************************

!********************************************************************************
! NACA00XX airfoil: x=[0,1].
!********************************************************************************
 function naca4digits(x) result(y)

 real(dp), intent(in) :: x
 real(dp)             :: y

 real(dp)             :: xx, xx2, xx3, xx4
 real(dp)             :: a, b, c, d, e, t

    t  = nacaxx * 0.01_dp
   xx  = x
   xx2 = xx*xx
   xx3 = xx*xx2
   xx4 = xx*xx3

    a =  0.2969_dp;
    b = -0.1260_dp;
    c = -0.3516_dp;
    d =  0.2843_dp;
!   e = -0.1015_dp; ! For finite thick TE
    e = -0.1036_dp; ! For zero thick TE

    y = 5.0_dp*t*( a*sqrt(xx) + b*xx + c*xx2 + d*xx3 + e*xx4 )

 end function naca4digits
!********************************************************************************

!********************************************************************************
! Slope of NACA00XX airfoil: x=[0,1].
!********************************************************************************
 function naca4digits_df(x) result(y)

 real(dp), intent(in) :: x
 real(dp)             :: y

 real(dp)             :: xx, xx2, xx3
 real(dp)             :: a, b, c, d, e, t

    t  = nacaxx * 0.01_dp
   xx  = x
   xx2 = xx*xx
   xx3 = xx*xx2

    a =  0.2969_dp;
    b = -0.1260_dp;
    c = -0.3516_dp;
    d =  0.2843_dp;
!   e = -0.1015_dp; ! For finite thick TE
    e = -0.1036_dp; ! For zero thick TE

   if ( abs(xx) < 1.0e-12_dp ) then
     y = 0.0_dp
   else
 !   y = 5.0_dp*t*( a*sqrt(xx) + b*xx + c*xx2 + d*xx3 + e*xx4 )
     y = 5.0_dp*t*( 0.5_dp*a/sqrt(xx) + b + 2.0_dp*c*xx + 3.0_dp*d*xx2 + 4.0_dp*e*xx3 )
   endif

 end function naca4digits_df
