!********************************************************************************
!********************************************************************************
!********************************************************************************
! Data-Based Airfoil functions
!********************************************************************************
!********************************************************************************
!********************************************************************************

!********************************************************************************
! Construct splines for a given set of discrete airfoil data.
!********************************************************************************
 subroutine construct_spline(filename)

 implicit none

 character(80), intent(in) :: filename
 integer(kd)                   :: i, nb

 real(dp) :: xp, yp, xmin, xmax

!----------------------------------------------------------------
! Read the airfoil data: discrete half-thickness data.
!
!                     y
!                     ^
!                     |
!                  o  |o
!               o     |    o
!              o      |       o
!             LE---------------TE--->x
!            xmin             xmax
!
! Datafile format:
!
!  [nuber of points]
!  [list of x-coordinates from LE to TE]
!  [list of y-coordinates from LE to TE]
!
! See below about how it is read.
!

  open(unit=1, file=filename, status="unknown", iostat=os)

  !Read the number of points:
   read(1,*) nd
   allocate( ay(4,nd) )
   allocate( xd(nd), yd(nd) )
 
  !Read xd(i)
   do i = 1, nd
    read(1,*) xd(i)
   end do

  !Read yd(i)
   do i = 1, nd
    read(1,*) yd(i)
   end do

  close(1)

   xmin = minval(xd)
   xmax = maxval(xd)

 !LE at x=0.
  if ( abs(xmin) > 1.0e-12_dp  ) then
   if (xmin < zero) xd = xd + abs(xmin)
   if (xmin > zero) xd = xd - abs(xmin)
  endif

   xmin = minval(xd)
   xmax = maxval(xd)

 !TE at x=1.
  if ( abs(xmax-one) > 1.0e-12_dp  ) then
   xd = xd/xmax
   yd = yd/xmax
  endif

!----------------------------------------------------------------
! Construct cubic spline: ax and ay

!(1)Use the arc length as a parameter:
!   call param(xd,yd,td,nd)
!   call construct_cubic_spline(xd, td,nd, 1, 0, zero, zero, ax)
!   call construct_cubic_spline(yd, td,nd, 1, 0, zero, zero, ay)

!(2)Use x as a parameter:

  !Natural spline
   call construct_cubic_spline(yd, xd,nd, 0, 0, zero, zero, ay)

!----------------------------------------------------------------
! Write out the airfoil geometry represented by a cubic spline.

  debug_mode_airfoil : if (debug_mode) then

   open(unit=10, file="spline_airfoil.dat", status="unknown", iostat=os)
   nb = 1000
   write(10,*) 'TITLE = "2D airfoil with spline"'
   write(10,*) 'VARIABLES = "x","y"'
   write(10,*) 'zone  i =', nb, ' f=point'
   do i = 1, nb
   !xp = [0,1]
    xp = (1.0_dp - real(i-1,dp)/real(nb-1,dp) )*xd(1)  &
       +           real(i-1,dp)/real(nb-1,dp)  *xd(nd)
    yp = spline_based_airfoil(xp,xd,ay,nd)
    write(10,'(2es25.15)') xp, yp
   end do

  endif debug_mode_airfoil 

 end subroutine construct_spline
!********************************************************************************

!********************************************************************************
! Spline-representation of an airfoil: x=[0,1].
!********************************************************************************
 function spline_based_airfoil(tp,t,a,n) result(fp)

 implicit none
 integer , parameter  :: dp = selected_real_kind(p=15)

 !input
 integer(kd) ,                 intent(in) :: n
 real(dp), dimension(n),   intent(in) :: t
 real(dp), dimension(4,n), intent(in) :: a
 real(dp),                 intent(in) :: tp

 !Output
 real(dp)                             :: fp

 !Local variables
 integer(kd) :: i

!-------------------------------------------------------------
! Find out in which interval t lies.

   i = 1
  do while (t(i) < tp)
   i = i + 1

   if (i > n) then
    write(*,*) " Requested paramete is out of range... "
    write(*,*) "   tp =  ", tp, " > 1.0... Stop at spline_based_airfoil()"
    stop
   endif

  end do

 !This takes care of the case: t(1)=tp.
  if (i == 1) then
   i = 2
  endif

  if ( tp < t(1) ) then
   write(*,*) " Requested paramete is out of range... "
   write(*,*) "  t(1) =  ", t(1)
   write(*,*) "    tp =  ", tp, " < t(1)... Stop at spline_based_airfoil()"
   stop
  endif

!-------------------------------------------------------------
! t is in between i and (i-1).
! then compute x

  fp =   a(1,i-1)                                    &
       + a(2,i-1)*(tp-t(i-1))                        &
       + a(3,i-1)*(tp-t(i-1))*(tp-t(i-1))            &
       + a(4,i-1)*(tp-t(i-1))*(tp-t(i-1))*(tp-t(i-1))

 return


 end function spline_based_airfoil
!********************************************************************************

!********************************************************************************
! Slope of spline_based_airfoil: x=[0,1].
!********************************************************************************
 function spline_based_airfoil_df(tp,t,a,n) result(df)

 implicit none
 integer , parameter  :: dp = selected_real_kind(p=15)

 !input
 integer(kd) ,                 intent(in) :: n
 real(dp), dimension(n),   intent(in) :: t
 real(dp), dimension(4,n), intent(in) :: a
 real(dp),                 intent(in) :: tp

 !Output
 real(dp)                             :: df

 !Local variables
 integer(kd) :: i

!-------------------------------------------------------------
! Find out in which interval t lies.

   i = 1

  do while (t(i) < tp)

   i = i + 1

   if (i > n) then
    write(*,*) " Requested paramete is out of range... "
    write(*,*) "   tp =  ", tp, " > 1.0... Stop at spline_based_airfoil()"
    stop
   endif

  end do

 !This takes care of the case: t(1)=tp.
  if (i == 1) then
   i = 2
  endif

  if ( tp < t(1) ) then
   write(*,*) " Requested paramete is out of range... "
   write(*,*) "  t(1) =  ", t(1)
   write(*,*) "    tp =  ", tp, " < t(1)... Stop at spline_based_airfoil()"
   stop
  endif

!-------------------------------------------------------------
! t is in between i and (i-1).
! then compute x

  df = a(2,i-1) + 2.0_dp*a(3,i-1)*(tp-t(i-1))             &
                + 3.0_dp*a(4,i-1)*(tp-t(i-1))*(tp-t(i-1))

 return

 end function spline_based_airfoil_df
!********************************************************************************


!************************************************************************
!* this program constructs a cubic spline of a function f(t)
!* t=0 to 1.
!* 
!* input:            n: number of points
!*          df_0, df_n: derivatives at the end points (t=0,1) 
!*
!* output:   a: 4x(n-1) spline matrix 
!*
!* note: in general, spline_clmp(fd,td,df_0,df_n,n,a) where
!*       (f(d),t(d)), d=1,...,n are the sample points. 
!*
!* Hiroaki nishikawa, October 29, 1998
!************************************************************************
  subroutine construct_cubic_spline(f,t,n,cnd0,cnd1,df_0,df_n,a)

  implicit none

 !Input
  integer(kd) ,           intent(in) :: n
  integer ,                 intent(in) :: cnd0, cnd1
  real(dp), dimension(n),   intent(in) :: f, t
  real(dp),                 intent(in) :: df_0, df_n

 !Output
  real(dp), dimension(4,n), intent(out) :: a

 !Local variables
  real(dp), dimension(n) :: h, q, u, z, l
  integer(kd)                :: i, j

!************************************************************************
!* a(1,:) are just the function values.
!************************************************************************ 

  do i = 1, n
   a(1,i) = f(i)
  end do

!************************************************************************
!* Construct the right hand side.
!************************************************************************ 

  do i = 1, n-1
   h(i) = t(i+1)-t(i)
  end do

 !Clamped splines:
  if (cnd0 == 1) q(1) = 3.0_dp*(a(1,2)-a(1,1))/h(1)-3.0_dp*df_0
  if (cnd1 == 1) q(n) = 3.0_dp*df_n-3.0_dp*(a(1,n)-a(1,n-1))/h(n-1)

  do i = 2, n-1
   q(i) = 3.0_dp*(a(1,i+1)-a(1,i))/h(i)-3.0_dp*(a(1,i)-a(1,i-1))/h(i-1)
  end do

!************************************************************************
!* Solve the linear system for a(3,:).
!************************************************************************ 

 !f''=0 (natural spline)
  if     (cnd0 == 0) then
   l(1) = 1.0_dp
   u(1) = 0.0_dp
   z(1) = 0.0_dp
 !f'=df_n (clamped spline)
  elseif (cnd0 == 1) then
   l(1) = 2.0_dp*h(1)
   u(1) = 0.5_dp
   z(1) = q(1)/l(1)
  endif

  do i = 2, n-1
   l(i) = 2.0_dp*(t(i+1)-t(i-1))-h(i-1)*u(i-1)
   u(i) = h(i)/l(i)
   z(i) = (q(i)-h(i-1)*z(i-1))/l(i)
  end do

 !f''=0 (natural spline)
  if     (cnd0 == 0) then
   l(n)   = 1.0_dp
   z(n)   = 0.0_dp
   a(3,n) = 0.0_dp
 !f'=df_n (clamped spline)
  elseif (cnd1 == 1) then
   l(n)   = h(n-1)*(2.0-u(n-1))
   z(n)   = (q(n)-h(n-1)*z(n-1))/l(n)
   a(3,n) = z(n)
  endif

  do j = n-1, 1, -1

 !---------------------------------------------------------
 ! Back substitution to compute a(3,:)

   a(3,j) = z(j) - u(j)*a(3,j+1)

 !---------------------------------------------------------
 ! Compute bj and dj from cj:
 !
 !  cubic_j = aj     +     bj*t +     cj*t^2 +     dj*t^3
 !          = a(1,j) + a(2,j)*t + a(3,j)*t^2 + a(4,j)*t^3

    a(2,j)=(a(1,j+1)-a(1,j))/h(j) - h(j)*(a(3,j+1)+2.0_dp*a(3,j))/3.0_dp
    a(4,j)=(a(3,j+1)-a(3,j))/(3.0_dp*h(j))

  end do

 !---------------------------------------------------------
 !---------------------------------------------------------

  return

  end subroutine construct_cubic_spline
!*********************************************************************** 
!*********************************************************************** 

!********************************************************************************
!********************************************************************************
!********************************************************************************
!********************************************************************************
!********************************************************************************

!********************************************************************************
! Construct splines for a given set of discrete airfoil data.
!********************************************************************************
 subroutine construct_spline_arc(filename)

 implicit none

 character(80), intent(in) :: filename
 integer(kd)                   :: i, nb

 real(dp) :: xp, yp, xmin, xmax, tp

!----------------------------------------------------------------
! Read the airfoil data: discrete half-thickness data.
!
!                     y
!                     ^
!                     |
!                  o  |o
!               o     |    o
!              o      |       o
!             LE---------------TE--->x
!            xmin             xmax
!
! Datafile format:
!
!  [nuber of points]
!  [list of x-coordinates from LE to TE]
!  [list of y-coordinates from LE to TE]
!
! See below about how it is read.
!

  open(unit=1, file=filename, status="unknown", iostat=os)

  !Read the number of points:
   read(1,*) nd
   allocate( ax(4,nd), ay(4,nd) )
   allocate( xd(nd), yd(nd), td(nd) )
 
  !Read xd(i)
   do i = 1, nd
    read(1,*) xd(i)
   end do

  !Read yd(i)
   do i = 1, nd
    read(1,*) yd(i)
   end do

  close(1)

   xmin = minval(xd)
   xmax = maxval(xd)

 !LE at x=0.
  if ( abs(xmin) > 1.0e-12_dp  ) then
   if (xmin < zero) xd = xd + abs(xmin)
   if (xmin > zero) xd = xd - abs(xmin)
  endif

   xmin = minval(xd)
   xmax = maxval(xd)

 !TE at x=1.
  if ( abs(xmax-one) > 1.0e-12_dp  ) then
   xd = xd/xmax
   yd = yd/xmax
  endif

!----------------------------------------------------------------
! Construct cubic spline with the arc-length as parameter: ax and ay

  !Parametrize the data.

   call parametrize(xd,yd,td,nd,tn)

  !Natural spline
   call construct_cubic_spline_arc(xd, td,nd, 0, 0, zero, zero, ax)
   call construct_cubic_spline_arc(yd, td,nd, 0, 0, zero, zero, ay)

!----------------------------------------------------------------
! Write out the airfoil geometry represented by a cubic spline.

  debug_mode_airfoil : if (debug_mode) then

   open(unit=10, file="spline_airfoil_arc.dat", status="unknown", iostat=os)
   nb = 1000
   write(10,*) 'TITLE = "2D airfoil with spline"'
   write(10,*) 'VARIABLES = "x","y"'
   write(10,*) 'zone  i =', nb, ' f=point'
   do i = 1, nb
   !tp = [0,1]
    tp = 1.0_dp/real(nb-1,dp)*(real(i-1,dp))
    xp = spline_based_airfoil_arc(tp,td,ax,nd)
    yp = spline_based_airfoil_arc(tp,td,ay,nd)
    write(10,'(2es25.15)') xp, yp
   end do

  endif debug_mode_airfoil 

 end subroutine construct_spline_arc
!********************************************************************************

!************************************************************************
!* This program constructs a parametrization of a curve in (x,y) plane
!* using arc-length as a parameter.
!* 
!* Input :  x, y : coordinates of the defining points.
!*
!* Output:     t : parameter values of x(t) and y(t).
!*
!*
!* Note: (x(i),y(i)) = ( x(t(i)), y(t(i)) ), i = 1, n.
!*
!* Hiroaki Nishikawa, October 29, 1998
!************************************************************************
 subroutine parametrize(x, y, t, n, tn)

 implicit none
 integer , parameter  :: dp = selected_real_kind(p=15)

 !input
 integer(kd) ,                 intent(in)  :: n
 real(dp), dimension(n),   intent(in)  :: x, y

 !Output
 real(dp), dimension(n),   intent(out) :: t
 real(dp),                 intent(out) :: tn

 !Local variables
 integer(kd) :: i

!************************************************************************
!* Compute the arc-length parameter.
!************************************************************************

   t(1) = zero
  do i = 2, n
   t(i) = t(i-1) + sqrt( (x(i)-x(i-1))**2 + (y(i)-y(i-1))**2 )
  end do

     tn = t(n)

!************************************************************************
!* Normalize the parameter such that t = [0,1].
!************************************************************************
  do i = 2, n
   t(i) = t(i)/t(n)
  end do

 return

 end subroutine parametrize
!************************************************************************
!************************************************************************

!************************************************************************
!* 
!* Input :  xp, yp : coordinates of a given point
!*
!* Output:     tp : parameter value for (xp,yp)
!*
!*
!* Note: (x(i),y(i)) = ( x(t(i)), y(t(i)) ), i = 1, n.
!*
!* Hiroaki Nishikawa, October 29, 1998
!************************************************************************
 subroutine find_t(xp,yp,tp, x,y,t,n,tn)

 implicit none
 integer , parameter  :: dp = selected_real_kind(p=15)

 !input
 integer(kd) ,                 intent(in)  :: n
 real(dp),                 intent(in)  :: xp, yp, tn
 real(dp), dimension(n),   intent(in)  :: x,  y, t

 !Output
 real(dp), intent(out) :: tp

 !Local variables
 integer(kd)  :: i, ip
 real(dp) :: dot
 logical :: found

!************************************************************************
!* Bracket the given point.
!* (Assumption: a curve is smooth, so that dot product of any two
!*  adjacent linear edge vectors taken along the curve is positive.)
!************************************************************************

   found = .false.
  loop_to_fined_t : do i = 2, n
   dot = (xp-x(i))*(xp-x(i-1)) + (yp-y(i))*(yp-y(i-1))
   if (dot < 0.0_dp) then
    ip = i 
    found = .true.
    exit loop_to_fined_t
   endif
  end do loop_to_fined_t

  if (.not.found) then
   write(*,*) " Bracketing (xp,yp) failed. Geometry may not be smooth..."
   write(*,*) " Stop at find_t()..."
   stop
  endif

!************************************************************************
!* Normalize the parameter such that t = [0,1].
!************************************************************************

  tp = t(ip-1) + sqrt( (xp-x(ip-1))**2 + (yp-y(ip-1))**2 )/tn

  if (tp > 1.0_dp) then
   write(*,*) " Parameter t > 1.0. Something is wrong..."
   write(*,*) "        n = ", n
   write(*,*) "     ip-1 = ", ip-1
   write(*,*) "     ip   = ", ip
   write(*,*) "  t(ip-1) = ", t(ip-1)
   write(*,*) "  t(ip  ) = ", t(ip)
   write(*,*) "       dt = ", sqrt( (xp-x(ip-1))**2 + (yp-y(ip-1))**2 )/tn
   write(*,*) "       tn = ", tn
   write(*,*) "       tp = ", tp
   write(*,*) " Stop in find_t()..."
   stop
  endif

 return

 end subroutine find_t
!************************************************************************
!************************************************************************

!********************************************************************************
! Spline-representation of an airfoil: t=[0,1].
!********************************************************************************
 function spline_based_airfoil_arc(tp,t,a,n) result(fp)

 implicit none
 integer , parameter  :: dp = selected_real_kind(p=15)

 !input
 integer(kd) ,                 intent(in) :: n
 real(dp), dimension(n),   intent(in) :: t
 real(dp), dimension(4,n), intent(in) :: a
 real(dp),                 intent(in) :: tp

 !Output
 real(dp)                             :: fp

 !Local variables
 integer(kd) :: i

!-------------------------------------------------------------
! Find out in which interval t lies.

   i = 1
  do while (t(i) < tp)
   i = i + 1

   if (i > n) then
    write(*,*) " Requested paramete is out of range... "
    write(*,*) "   tp =  ", tp, " > 1.0... Stop at spline_based_airfoil()"
    stop
   endif

  end do

 !This takes care of the case: t(1)=tp.
  if (i == 1) then
   i = 2
  endif

  if ( tp < t(1) ) then
   write(*,*) " Requested paramete is out of range... "
   write(*,*) "  t(1) =  ", t(1)
   write(*,*) "    tp =  ", tp, " < t(1)... Stop at spline_based_airfoil()"
   stop
  endif

!-------------------------------------------------------------
! t is in between i and (i-1).
! then compute x

  fp =   a(1,i-1)                                    &
       + a(2,i-1)*(tp-t(i-1))                        &
       + a(3,i-1)*(tp-t(i-1))*(tp-t(i-1))            &
       + a(4,i-1)*(tp-t(i-1))*(tp-t(i-1))*(tp-t(i-1))

 return


 end function spline_based_airfoil_arc
!********************************************************************************

!********************************************************************************
! Slope of spline_based_airfoil: x=[0,1].
!********************************************************************************
 function spline_based_airfoil_df_arc(tp,t,a,n) result(df)

 implicit none
 integer , parameter  :: dp = selected_real_kind(p=15)

 !input
 integer(kd) ,                 intent(in) :: n
 real(dp), dimension(n),   intent(in) :: t
 real(dp), dimension(4,n), intent(in) :: a
 real(dp),                 intent(in) :: tp

 !Output
 real(dp)                             :: df

 !Local variables
 integer(kd) :: i

!-------------------------------------------------------------
! Find out in which interval t lies.

   i = 1

  do while (t(i) < tp)

   i = i + 1

   if (i > n) then
    write(*,*) " Requested paramete is out of range... "
    write(*,*) "   tp =  ", tp, " > 1.0... Stop at spline_based_airfoil()"
    stop
   endif

  end do

 !This takes care of the case: t(1)=tp.
  if (i == 1) then
   i = 2
  endif

  if ( tp < t(1) ) then
   write(*,*) " Requested paramete is out of range... "
   write(*,*) "  t(1) =  ", t(1)
   write(*,*) "    tp =  ", tp, " < t(1)... Stop at spline_based_airfoil()"
   stop
  endif

!-------------------------------------------------------------
! t is in between i and (i-1).
! then compute x

  df = a(2,i-1) + 2.0_dp*a(3,i-1)*(tp-t(i-1))             &
                + 3.0_dp*a(4,i-1)*(tp-t(i-1))*(tp-t(i-1))

 return

 end function spline_based_airfoil_df_arc
!********************************************************************************


!************************************************************************
!* this program constructs a cubic spline of a function f(t)
!* t=0 to 1.
!* 
!* input:            n: number of points
!*          df_0, df_n: derivatives at the end points (t=0,1) 
!*
!* output:   a: 4x(n-1) spline matrix 
!*
!* note: in general, spline_clmp(fd,td,df_0,df_n,n,a) where
!*       (f(d),t(d)), d=1,...,n are the sample points. 
!*
!* Hiroaki nishikawa, October 29, 1998
!************************************************************************
  subroutine construct_cubic_spline_arc(f,t,n,cnd0,cnd1,df_0,df_n,a)

  implicit none

 !Input
  integer(kd) ,                 intent(in) :: n
  integer       ,                 intent(in) :: cnd0, cnd1
  real(dp), dimension(n),   intent(in) :: f, t
  real(dp),                 intent(in) :: df_0, df_n

 !Output
  real(dp), dimension(4,n), intent(out) :: a

 !Local variables
  real(dp), dimension(n) :: h, q, u, z, l
  integer(kd)                :: i, j

!************************************************************************
!* a(1,:) are just the function values.
!************************************************************************ 

  do i = 1, n
   a(1,i) = f(i)
  end do

!************************************************************************
!* Construct the right hand side.
!************************************************************************ 

  do i = 1, n-1
   h(i) = t(i+1)-t(i)
  end do

 !Clamped splines:
  if (cnd0 == 1) q(1) = 3.0_dp*(a(1,2)-a(1,1))/h(1)-3.0_dp*df_0
  if (cnd1 == 1) q(n) = 3.0_dp*df_n-3.0_dp*(a(1,n)-a(1,n-1))/h(n-1)

  do i = 2, n-1
   q(i) = 3.0_dp*(a(1,i+1)-a(1,i))/h(i)-3.0_dp*(a(1,i)-a(1,i-1))/h(i-1)
  end do

!************************************************************************
!* Solve the linear system for a(3,:).
!************************************************************************ 

 !f''=0 (natural spline)
  if     (cnd0 == 0) then
   l(1) = 1.0_dp
   u(1) = 0.0_dp
   z(1) = 0.0_dp
 !f'=df_n (clamped spline)
  elseif (cnd0 == 1) then
   l(1) = 2.0_dp*h(1)
   u(1) = 0.5_dp
   z(1) = q(1)/l(1)
  endif

  do i = 2, n-1
   l(i) = 2.0_dp*(t(i+1)-t(i-1))-h(i-1)*u(i-1)
   u(i) = h(i)/l(i)
   z(i) = (q(i)-h(i-1)*z(i-1))/l(i)
  end do

 !f''=0 (natural spline)
  if     (cnd0 == 0) then
   l(n)   = 1.0_dp
   z(n)   = 0.0_dp
   a(3,n) = 0.0_dp
 !f'=df_n (clamped spline)
  elseif (cnd1 == 1) then
   l(n)   = h(n-1)*(2.0-u(n-1))
   z(n)   = (q(n)-h(n-1)*z(n-1))/l(n)
   a(3,n) = z(n)
  endif

  do j = n-1, 1, -1

 !---------------------------------------------------------
 ! Back substitution to compute a(3,:)

   a(3,j) = z(j) - u(j)*a(3,j+1)

 !---------------------------------------------------------
 ! Compute bj and dj from cj:
 !
 !  cubic_j = aj     +     bj*t +     cj*t^2 +     dj*t^3
 !          = a(1,j) + a(2,j)*t + a(3,j)*t^2 + a(4,j)*t^3

    a(2,j)=(a(1,j+1)-a(1,j))/h(j) - h(j)*(a(3,j+1)+2.0_dp*a(3,j))/3.0_dp
    a(4,j)=(a(3,j+1)-a(3,j))/(3.0_dp*h(j))

  end do

 !---------------------------------------------------------
 !---------------------------------------------------------

  return

  end subroutine construct_cubic_spline_arc
!*********************************************************************** 
!*********************************************************************** 

!********************************************************************************
!********************************************************************************
!********************************************************************************
!********************************************************************************
!********************************************************************************
!********************************************************************************


!********************************************************************************
!* Check the volume of all types of elements.
!*
!********************************************************************************
  subroutine volume_check(negative_volume)
  implicit none

  logical, dimension(3), intent(out) :: negative_volume

  real(dp) :: x1,x2,x3,x4, y1,y2,y3,y4, z1,z2,z3,z4
  real(dp) :: x5,x6,x7,x8, y5,y6,y7,y8, z5,z6,z7,z8
  real(dp) :: volume, vol_max, vol_min, vol_ave

  integer(kd)               :: i, n_negative_vol, itet, ihex, iprs
  integer(kd), dimension(8) :: v
  character(80)         :: i_char, filename

  itet = 1
  ihex = 2
  iprs = 3
  negative_volume = .false.

!--------------------------------------------------------------------
!--------------------------------------------------------------------
! (1)Check Tetrahedral elements
!--------------------------------------------------------------------
!--------------------------------------------------------------------
 tet_vol_check : if (ntet > 0) then

   n_negative_vol =  0
          vol_max = -1.0_dp
          vol_min =  1.0e+15_dp
          vol_ave =  0.0_dp

  !-------------------------------------------------------------
  ! Loop over tetrahedra and check the volumne one by one.
  !-------------------------------------------------------------
   do i = 1, ntet

    x1 = node( tet(i,1) )%x
    y1 = node( tet(i,1) )%y
    z1 = node( tet(i,1) )%z

    x2 = node( tet(i,2) )%x
    y2 = node( tet(i,2) )%y
    z2 = node( tet(i,2) )%z

    x3 = node( tet(i,3) )%x
    y3 = node( tet(i,3) )%y
    z3 = node( tet(i,3) )%z

    x4 = node( tet(i,4) )%x
    y4 = node( tet(i,4) )%y
    z4 = node( tet(i,4) )%z

     volume = tet_volume(x1,x2,x3,x4, y1,y2,y3,y4, z1,z2,z3,z4)

    vol_max = max(vol_max,volume)
    vol_min = min(vol_min,volume)
    vol_ave = vol_ave + volume

    if (volume < 0.0_dp) then

     write(8933,*) " Negative volume tet at element = ", i

     !Write a Tecplot file for the negative-volume tetrahedra,
     !only for the first 20 tetra (to avoid too many files).
     if (n_negative_vol < 21) then

      write( i_char  , '(i0)' ) i
      filename = "negative_vol_tet_" // trim(i_char) // "_tec.dat"
      open(unit=3, file=filename, status="unknown", iostat=os)
      write(3,*) 'TITLE = ', "negative_vol_tet_" // trim(i_char)
      write(3,*) 'VARIABLES = "x","y","z"'
      write(3,*) 'ZONE  N=', 4,',E=', 1,' , et=tetrahedron, F=FEPOINT'
      write(3,'(3ES20.10)') x1, y1, z1
      write(3,'(3ES20.10)') x2, y2, z2
      write(3,'(3ES20.10)') x3, y3, z3
      write(3,'(3ES20.10)') x4, y4, z4
      write(3,'(4i10)'    )  1, 2, 3, 4
      close(3)

     endif

     n_negative_vol = n_negative_vol + 1

     ! Display a WARNING MESSAGE
     if (n_negative_vol == 1) then
      write(*,*)
      write(*,*) "!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!"
      write(*,*) "!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!"
      write(*,*) "!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!"
      write(*,*) " Negative tet volume deteceted. See fort.8933..."
      write(*,*) "!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!"
      write(*,*) "!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!"
      write(*,*) "!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!"
      write(*,*)
     endif

    endif

   end do
  !-------------------------------------------------------------
  ! End of loop over tetrahedra
  !-------------------------------------------------------------

   vol_ave = vol_ave / real(ntet,dp)

   if (n_negative_vol == 0) then
     write(*,*)
     write(*,*) " Negative tetra volume not detected."
     write(*,*)
   endif

   write(*,*)
   write(*,'(a,es26.16)') " Minimum tetrahedral volume = ", vol_min
   write(*,'(a,es26.16)') " Maximum tetrahedral volume = ", vol_max
   write(*,'(a,es26.16)') " Average tetrahedral volume = ", vol_ave
   write(*,*)

   if (n_negative_vol > 0) then
     write(*,*) " Tetrahedra with negative volume created....."
     write(*,*) "  # of tets having negative volume = ", n_negative_vol
     negative_volume(itet) = .true.
   endif

 endif tet_vol_check
!--------------------------------------------------------------------
!--------------------------------------------------------------------
! End fo (1)Check Tetrahedral elements
!--------------------------------------------------------------------
!--------------------------------------------------------------------

!--------------------------------------------------------------------
!--------------------------------------------------------------------
! (2)Check Hexahedral elements
!--------------------------------------------------------------------
!--------------------------------------------------------------------
 hex_vol_check : if (nhex > 0) then

   n_negative_vol = 0
   vol_max = -1.0_dp
   vol_min =  1.0e+15_dp
   vol_ave =  0.0_dp

  !-------------------------------------------------------------
  ! Loop over hex and check the volumne one by one.
  !-------------------------------------------------------------
   do i = 1, nhex

    v(1:8) =  hex(i,1:8)

    x1 = node( v(1) )%x
    y1 = node( v(1) )%y
    z1 = node( v(1) )%z

    x2 = node( v(2) )%x
    y2 = node( v(2) )%y
    z2 = node( v(2) )%z

    x3 = node( v(3) )%x
    y3 = node( v(3) )%y
    z3 = node( v(3) )%z

    x4 = node( v(4) )%x
    y4 = node( v(4) )%y
    z4 = node( v(4) )%z

    x5 = node( v(5) )%x
    y5 = node( v(5) )%y
    z5 = node( v(5) )%z

    x6 = node( v(6) )%x
    y6 = node( v(6) )%y
    z6 = node( v(6) )%z

    x7 = node( v(7) )%x
    y7 = node( v(7) )%y
    z7 = node( v(7) )%z

    x8 = node( v(8) )%x
    y8 = node( v(8) )%y
    z8 = node( v(8) )%z

  !Cut into 6 tetrahedra and compute the volume of hex:

     volume = 0.0_dp
     volume = volume + tet_volume( x1, x4, x5, x6, &
                                   y1, y4, y5, y6, &
                                   z1, z4, z5, z6  )

     volume = volume + tet_volume( x4, x8, x5, x6, &
                                   y4, y8, y5, y6, &
                                   z4, z8, z5, z6  )

     volume = volume + tet_volume( x3, x2, x6, x4, &
                                   y3, y2, y6, y4, &
                                   z3, z2, z6, z4  )

     volume = volume + tet_volume( x3, x6, x7, x4, &
                                   y3, y6, y7, y4, &
                                   z3, z6, z7, z4  )

     volume = volume + tet_volume( x1, x2, x4, x6, &
                                   y1, y2, y4, y6, &
                                   z1, z2, z4, z6  )

     volume = volume + tet_volume( x4, x7, x8, x6, &
                                   y4, y7, y8, y6, &
                                   z4, z7, z8, z6  )

    vol_max = max(vol_max,volume)
    vol_min = min(vol_min,volume)
    vol_ave = vol_ave + volume

    if (volume < 0.0_dp) then

     write(8933,*) " Negative volume hex at element = ", i

     !Write a Tecplot file for the negative-volume tetrahedra,
     !only for the first 20 tetra (to avoid too many files).
     if (n_negative_vol < 21) then

      write( i_char  , '(i0)' ) i
      filename = "negative_vol_hex_" // trim(i_char) // "_tec.dat"
      open(unit=3, file=filename, status="unknown", iostat=os)
      write(3,*) 'TITLE = ', "negative_vol_tet_" // trim(i_char)
      write(3,*) 'VARIABLES = "x","y","z"'
      write(3,*) 'ZONE  N=', 8,',E=', 1,' , et=tetrahedron, F=FEPOINT'
      write(3,'(3ES20.10)') x1, y1, z1
      write(3,'(3ES20.10)') x2, y2, z2
      write(3,'(3ES20.10)') x3, y3, z3
      write(3,'(3ES20.10)') x4, y4, z4
      write(3,'(3ES20.10)') x5, y5, z5
      write(3,'(3ES20.10)') x6, y6, z6
      write(3,'(3ES20.10)') x7, y7, z7
      write(3,'(3ES20.10)') x8, y8, z8
      write(3,'(4i10)'    )  1, 2, 3, 4, 5, 6, 7, 8
      close(3)

     endif

     n_negative_vol = n_negative_vol + 1

     ! Display a WARNING MESSAGE
     if (n_negative_vol == 1) then
      write(*,*)
      write(*,*) "!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!"
      write(*,*) "!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!"
      write(*,*) "!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!"
      write(*,*) " Negative Hex volume deteceted. See fort.8933..."
      write(*,*) "!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!"
      write(*,*) "!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!"
      write(*,*) "!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!"
      write(*,*)
     endif

    endif

   end do
  !-------------------------------------------------------------
  ! End of loop over hex
  !-------------------------------------------------------------

   vol_ave = vol_ave / real(nhex,dp)

   if (n_negative_vol == 0) then
     write(*,*)
     write(*,*) " Negative hex volume not detected. Great! "
     write(*,*)
   endif

   write(*,*)
   write(*,'(a,es26.16)') " Minimum hexahedral volume = ", vol_min
   write(*,'(a,es26.16)') " Maximum hexahedral volume = ", vol_max
   write(*,'(a,es26.16)') " Average hexahedral volume = ", vol_ave
   write(*,*)

   if (n_negative_vol > 0) then
     write(*,*) " Hexahedra with negative volume created....."
     write(*,*) "  # of hex having negative volume = ", n_negative_vol
     negative_volume(ihex) = .true.
   endif

 endif hex_vol_check

!--------------------------------------------------------------------
!--------------------------------------------------------------------
! End fo (2)Check Hexahedral elements
!--------------------------------------------------------------------
!--------------------------------------------------------------------


!--------------------------------------------------------------------
!--------------------------------------------------------------------
! (3)Check Prismatic elements
!--------------------------------------------------------------------
!--------------------------------------------------------------------
 prs_vol_check : if (nprs > 0) then

   n_negative_vol = 0
   vol_max = -1.0_dp
   vol_min =  1.0e+15_dp
   vol_ave =  0.0_dp

  !-------------------------------------------------------------
  ! Loop over prism and check the volumne one by one.
  !-------------------------------------------------------------
   do i = 1, nprs

    v(1:6) =  prs(i,1:6)

    x1 = node( v(1) )%x
    y1 = node( v(1) )%y
    z1 = node( v(1) )%z

    x2 = node( v(2) )%x
    y2 = node( v(2) )%y
    z2 = node( v(2) )%z

    x3 = node( v(3) )%x
    y3 = node( v(3) )%y
    z3 = node( v(3) )%z

    x4 = node( v(4) )%x
    y4 = node( v(4) )%y
    z4 = node( v(4) )%z

    x5 = node( v(5) )%x
    y5 = node( v(5) )%y
    z5 = node( v(5) )%z

    x6 = node( v(6) )%x
    y6 = node( v(6) )%y
    z6 = node( v(6) )%z

  !Cut prism into 3 tetrahedra and compute the volume of prism:

     volume = 0.0_dp
     volume = volume + tet_volume( x1, x2, x3, x4, &
                                   y1, y2, y3, y4, &
                                   z1, z2, z3, z4  )

     volume = volume + tet_volume( x5, x6, x3, x4, &
                                   y5, y6, y3, y4, &
                                   z5, z6, z3, z4  )

     volume = volume + tet_volume( x5, x3, x2, x4, &
                                   y5, y3, y2, y4, &
                                   z5, z3, z2, z4  )

    vol_max = max(vol_max,volume)
    vol_min = min(vol_min,volume)
    vol_ave = vol_ave + volume

    if (volume < 0.0_dp) then

     write(8933,*) " Negative volume prism at element = ", i

     !Write a Tecplot file for the negative-volume tetrahedra,
     !only for the first 20 tetra (to avoid too many files).
     if (n_negative_vol < 21) then

      write( i_char  , '(i0)' ) i
      filename = "negative_vol_prism_" // trim(i_char) // "_tec.dat"
      open(unit=3, file=filename, status="unknown", iostat=os)
      write(3,*) 'TITLE = ', "negative_vol_tet_" // trim(i_char)
      write(3,*) 'VARIABLES = "x","y","z"'
      write(3,*) 'ZONE  N=', 6,',E=', 1,' , et=tetrahedron, F=FEPOINT'
      write(3,'(3ES20.10)') x1, y1, z1
      write(3,'(3ES20.10)') x2, y2, z2
      write(3,'(3ES20.10)') x3, y3, z3
      write(3,'(3ES20.10)') x4, y4, z4
      write(3,'(3ES20.10)') x5, y5, z5
      write(3,'(3ES20.10)') x6, y6, z6
      write(3,'(4i10)'    )  1, 2, 3, 4, 5, 6
      close(3)

     endif

     n_negative_vol = n_negative_vol + 1

     ! Display a WARNING MESSAGE
     if (n_negative_vol == 1) then
      write(*,*)
      write(*,*) "!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!"
      write(*,*) "!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!"
      write(*,*) "!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!"
      write(*,*) " Negative Prism volume deteceted. See fort.8933..."
      write(*,*) "!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!"
      write(*,*) "!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!"
      write(*,*) "!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!"
      write(*,*)
     endif

    endif

   end do
  !-------------------------------------------------------------
  ! End of loop over prism
  !-------------------------------------------------------------

   vol_ave = vol_ave / real(nprs,dp)

   if (n_negative_vol == 0) then
     write(*,*)
     write(*,*) " Negative prism volume not detected. Great! "
     write(*,*)
   endif

   write(*,*)
   write(*,'(a,es26.16)') " Minimum prismatic volume = ", vol_min
   write(*,'(a,es26.16)') " Maximum prismatic volume = ", vol_max
   write(*,'(a,es26.16)') " Average prismatic volume = ", vol_ave
   write(*,*)

   if (n_negative_vol > 0) then
     write(*,*) " prisms with negative volume created....."
     write(*,*) "  # of prisms having negative volume = ", n_negative_vol
     negative_volume(iprs) = .true.
   endif

 endif prs_vol_check

!--------------------------------------------------------------------
!--------------------------------------------------------------------
! End fo (3)Check Prismatic elements
!--------------------------------------------------------------------
!--------------------------------------------------------------------


  end subroutine volume_check

!*******************************************************************************
! Compute the volume of a tetrahedron defined by 4 vertices:
!
!       (x1,y1,z1), (x2,y2,z2), (x3,y3,z3), (x4,y4,z4),
!
! which are ordered as follows:
!
!            1
!            o
!           /| .
!          / |   .
!         /  |     .
!        /   |       .
!     2 o----|-------o 3
!        \   |     .
!         \  |    .
!          \ |  .
!           \|.
!            o
!            4
!
! Note: Volume = volume integral of 1 = 1/3 * volume integral of div(x,y,z) dV
!              = surface integral of (x,y,z)*dS
!              = sum of [ (xc,yc,zc)*area_vector ] over triangular faces.
!
! where the last step is exact because (x,y,z) vary linearly over the triangle.
! There are other ways to compute the volume, of course.
!
!*******************************************************************************
 function tet_volume(x1,x2,x3,x4, y1,y2,y3,y4, z1,z2,z3,z4)

 implicit none

 integer , parameter :: dp = selected_real_kind(15) !Double precision

 !Input
 real(dp), intent(in)   :: x1,x2,x3,x4, y1,y2,y3,y4, z1,z2,z3,z4
 !Output
 real(dp)               :: tet_volume

 real(dp)               :: xc, yc, zc
 real(dp), dimension(3) :: area
 integer(kd)                :: ix=1, iy=2, iz=3


 tet_volume = 0.0_dp

! Triangle 1-3-2

   !Centroid of the triangular face
      xc = (x1+x3+x2)/3.0_dp
      yc = (y1+y3+y2)/3.0_dp
      zc = (z1+z3+z2)/3.0_dp
   !Outward normal surface vector
   area = triangle_area_vector(x1,x3,x2, y1,y3,y2, z1,z3,z2)

   tet_volume = tet_volume + ( xc*area(ix) + yc*area(iy) + zc*area(iz) )

! Triangle 1-4-3

   !Centroid of the triangular face
      xc = (x1+x4+x3)/3.0_dp
      yc = (y1+y4+y3)/3.0_dp
      zc = (z1+z4+z3)/3.0_dp
   !Outward normal surface vector
   area = triangle_area_vector(x1,x4,x3, y1,y4,y3, z1,z4,z3)

   tet_volume = tet_volume + ( xc*area(ix) + yc*area(iy) + zc*area(iz) )

! Triangle 1-2-4

   !Centroid of the triangular face
      xc = (x1+x2+x4)/3.0_dp
      yc = (y1+y2+y4)/3.0_dp
      zc = (z1+z2+z4)/3.0_dp
   !Outward normal surface vector
   area = triangle_area_vector(x1,x2,x4, y1,y2,y4, z1,z2,z4)

   tet_volume = tet_volume + ( xc*area(ix) + yc*area(iy) + zc*area(iz) )

! Triangle 2-3-4

   !Centroid of the triangular face
      xc = (x2+x3+x4)/3.0_dp
      yc = (y2+y3+y4)/3.0_dp
      zc = (z2+z3+z4)/3.0_dp
   !Outward normal surface vector
   area = triangle_area_vector(x2,x3,x4, y2,y3,y4, z2,z3,z4)

   tet_volume = tet_volume + ( xc*area(ix) + yc*area(iy) + zc*area(iz) )

   tet_volume = tet_volume / 3.0_dp

 end function tet_volume

!*******************************************************************************
! Compute the area of a triangle in 3D defined by 3 vertices:
!
!       (x1,y1,z1), (x2,y2,z2), (x3,y3,z3),
!
! which is assumed to be ordered clockwise.
!
!     1             2
!      o------------o
!       \         .
!        \       . --------->
!         \    .
!          \ .
!           o
!           3
!
! Note: Area is a vector based on the right-hand rule: 
!       when wrapping the right hand around the triangle with the fingers in the
!       direction of the vertices [1,2,3], the thumb points in the positive
!       direction of the area.
!
! Note: Area vector is computed as the cross product of edge vectors [31] and [32].
!
!*******************************************************************************
 function triangle_area_vector(x1,x2,x3, y1,y2,y3, z1,z2,z3) result(area_vector)
 
 implicit none
 integer , parameter :: dp = selected_real_kind(15) !Double precision

 !Input
  real(dp), intent(in)   :: x1,x2,x3, y1,y2,y3, z1,z2,z3
 !Output
  real(dp), dimension(3) :: area_vector

  integer(kd) :: ix=1, iy=2, iz=3

   area_vector(ix) = 0.5_dp*( (y1-y3)*(z2-z3)-(z1-z3)*(y2-y3) )
   area_vector(iy) = 0.5_dp*( (z1-z3)*(x2-x3)-(x1-x3)*(z2-z3) )
   area_vector(iz) = 0.5_dp*( (x1-x3)*(y2-y3)-(y1-y3)*(x2-x3) )

 end function triangle_area_vector


!*******************************************************************************
! Compute the unit area vector of a triangle in 3D.
!
!*******************************************************************************
 function unit_triangle_area_vector(x1,x2,x3, y1,y2,y3, z1,z2,z3) result(area_vector)
 
 implicit none
 integer , parameter :: dp = selected_real_kind(15) !Double precision

 !Input
  real(dp), intent(in)   :: x1,x2,x3, y1,y2,y3, z1,z2,z3
 !Output
  real(dp), dimension(3) :: area_vector

  real(dp) :: mag
  integer(kd)  :: ix=1, iy=2, iz=3

   area_vector(ix) = 0.5_dp*( (y1-y3)*(z2-z3)-(z1-z3)*(y2-y3) )
   area_vector(iy) = 0.5_dp*( (z1-z3)*(x2-x3)-(x1-x3)*(z2-z3) )
   area_vector(iz) = 0.5_dp*( (x1-x3)*(y2-y3)-(y1-y3)*(x2-x3) )

   mag = sqrt(   area_vector(ix)**2 &
               + area_vector(iy)**2 &
               + area_vector(iz)**2 )

   if (mag < 1.0e-18) then
    write(*,*) "!!!!!!!!!!!!!!!!!!! Very small area vector...: Area = ", mag
    stop
   endif

   area_vector = area_vector / mag

 end function unit_triangle_area_vector

!********************************************************************************
!* Check non-planarity of quad faces.
!*
!* Note: All faces are oriented clockwise to give an outward area vector.
!*
!********************************************************************************
  subroutine non_planarity_check
  implicit none

  real(dp) :: x1,x2,x3,x4, y1,y2,y3,y4, z1,z2,z3,z4
  real(dp) :: cos_max, cos_min, cos_ave

  integer(kd)               :: i, k, nqface
  integer(kd), dimension(8) :: v

  !3 quad-faces for prism, 6 quad-faces for hex.
  integer(kd), dimension(6,4) :: face

  real(dp), dimension(3) :: unit_norm01, unit_norm02
  real(dp)               :: cos_p1, cos_p2, cos_p

   cos_max = -1.0_dp
   cos_min =  1.0e+15_dp
   cos_ave =  0.0_dp
    nqface = 0

!--------------------------------------------------------------------
!--------------------------------------------------------------------
! (2)Loop over Hexahedral elements
!
!      8 ______________ 7 
!       /             /|
!      /             / |
!     /____________ /  |
!    5|  |         |6  |
!     |  |         |   |
!     |  |         |   |
!     |  |4________|___|3
!     |  /         |  /
!     | /          | /
!     |/___________|/
!     1            2
!
!--------------------------------------------------------------------
!--------------------------------------------------------------------
 hex_check : if (nhex > 0) then

  !-------------------------------------------------------------
  ! Loop over hex and check quad faces  one by one.
  !-------------------------------------------------------------
   do i = 1, nhex

    v(1:8) =  hex(i,1:8)

    face(1, 1) = v(1)
    face(1, 2) = v(4)
    face(1, 3) = v(3)
    face(1, 4) = v(2)

    face(2, 1) = v(5)
    face(2, 2) = v(6)
    face(2, 3) = v(7)
    face(2, 4) = v(8)

    face(3, 1) = v(1)
    face(3, 2) = v(2)
    face(3, 3) = v(6)
    face(3, 4) = v(5)

    face(4, 1) = v(3)
    face(4, 2) = v(4)
    face(4, 3) = v(8)
    face(4, 4) = v(7)

    face(5, 1) = v(1)
    face(5, 2) = v(5)
    face(5, 3) = v(8)
    face(5, 4) = v(4)

    face(6, 1) = v(2)
    face(6, 2) = v(3)
    face(6, 3) = v(7)
    face(6, 4) = v(6)

    do k = 1, 6

     nqface = nqface + 1

     x1 = node( face(k,1) )%x
     y1 = node( face(k,1) )%y
     z1 = node( face(k,1) )%z

     x2 = node( face(k,2) )%x
     y2 = node( face(k,2) )%y
     z2 = node( face(k,2) )%z

     x3 = node( face(k,3) )%x
     y3 = node( face(k,3) )%y
     z3 = node( face(k,3) )%z

     x4 = node( face(k,4) )%x
     y4 = node( face(k,4) )%y
     z4 = node( face(k,4) )%z

   !Compute the dot product of unit normals of triangular faces within the quad:
   !There are two possible pairs of triangular faces.
   !The dot product is equal to cos(angle) because the normals are unit vectors.

     unit_norm01 = unit_triangle_area_vector(x1,x2,x3, y1,y2,y3, z1,z2,z3)
     unit_norm02 = unit_triangle_area_vector(x1,x3,x4, y1,y3,y4, z1,z3,z4)

     cos_p1 = unit_norm01(1)*unit_norm02(1) &
            + unit_norm01(2)*unit_norm02(2) &
            + unit_norm01(3)*unit_norm02(3)

     unit_norm01 = unit_triangle_area_vector(x1,x2,x4, y1,y2,y4, z1,z2,z4)
     unit_norm02 = unit_triangle_area_vector(x2,x3,x4, y2,y3,y4, z2,z3,z4)

     cos_p2 = unit_norm01(1)*unit_norm02(1) &
            + unit_norm01(2)*unit_norm02(2) &
            + unit_norm01(3)*unit_norm02(3)

     cos_p = max(cos_p1, cos_p2)

    cos_max = max(cos_max,cos_p)
    cos_min = min(cos_min,cos_p)
    cos_ave = cos_ave + cos_p

    end do

   end do
  !-------------------------------------------------------------
  ! End of loop over hex
  !-------------------------------------------------------------

 endif hex_check

!--------------------------------------------------------------------
!--------------------------------------------------------------------
! End fo (2)Loop over Hexahedral elements
!--------------------------------------------------------------------
!--------------------------------------------------------------------

!--------------------------------------------------------------------
!--------------------------------------------------------------------
! (2)Loop over Prismatic elements
!
!        6
!       / .
!      /      .
!     /________ 
!    4|  |      |5
!     |  |      |
!     |  |      |
!     |  |3     |
!     |  /  .   |
!     | /     . |
!     |/________|
!     1            2
!
!--------------------------------------------------------------------
!--------------------------------------------------------------------
 prs_check : if (nprs > 0) then

  !-------------------------------------------------------------
  ! Loop over prisms and check quad faces one by one.
  !-------------------------------------------------------------
   do i = 1, nprs

    v(1:6) =  prs(i,1:6)

    face(1, 1) = v(1)
    face(1, 2) = v(2)
    face(1, 3) = v(5)
    face(1, 4) = v(4)

    face(2, 1) = v(3)
    face(2, 2) = v(1)
    face(2, 3) = v(4)
    face(2, 4) = v(6)

    face(3, 1) = v(2)
    face(3, 2) = v(3)
    face(3, 3) = v(6)
    face(3, 4) = v(5)

    do k = 1, 3

     nqface = nqface + 1

     x1 = node( face(k,1) )%x
     y1 = node( face(k,1) )%y
     z1 = node( face(k,1) )%z

     x2 = node( face(k,2) )%x
     y2 = node( face(k,2) )%y
     z2 = node( face(k,2) )%z

     x3 = node( face(k,3) )%x
     y3 = node( face(k,3) )%y
     z3 = node( face(k,3) )%z

     x4 = node( face(k,4) )%x
     y4 = node( face(k,4) )%y
     z4 = node( face(k,4) )%z

   !Compute the dot product of unit normals of triangular faces within the quad:
   !There are two possible pairs of triangular faces.
   !The dot product is equal to cos(angle) because the normals are unit vectors.

     unit_norm01 = unit_triangle_area_vector(x1,x2,x3, y1,y2,y3, z1,z2,z3)
     unit_norm02 = unit_triangle_area_vector(x1,x3,x4, y1,y3,y4, z1,z3,z4)

     cos_p1 = unit_norm01(1)*unit_norm02(1) &
            + unit_norm01(2)*unit_norm02(2) &
            + unit_norm01(3)*unit_norm02(3)

     unit_norm01 = unit_triangle_area_vector(x1,x2,x4, y1,y2,y4, z1,z2,z4)
     unit_norm02 = unit_triangle_area_vector(x2,x3,x4, y2,y3,y4, z2,z3,z4)

     cos_p2 = unit_norm01(1)*unit_norm02(1) &
            + unit_norm01(2)*unit_norm02(2) &
            + unit_norm01(3)*unit_norm02(3)

     cos_p = max(cos_p1, cos_p2)

    cos_max = max(cos_max,cos_p)
    cos_min = min(cos_min,cos_p)
    cos_ave = cos_ave + cos_p

    end do

   end do
  !-------------------------------------------------------------
  ! End of loop over hex
  !-------------------------------------------------------------

 endif prs_check

!--------------------------------------------------------------------
!--------------------------------------------------------------------
! End of (2)Loop over Prismatic elements
!--------------------------------------------------------------------
!--------------------------------------------------------------------


   cos_ave = cos_ave / real(nqface,dp)

   write(*,*)
   write(*,*) " Non-planarity:"
   write(*,*) "   Each quad face is split into two triangles: T1 and T2."
   write(*,*) "   Dot product of unit tria-face normals computed: n(T1)*n(T2)."
   write(*,*) "   Two possible splits considered, and the larger is taken."
   write(*,*)
   write(*,'(a,es26.16)') " Minimum  = ", cos_min
   write(*,'(a,es26.16)') " Maximum  = ", cos_max
   write(*,'(a,es26.16)') " Average  = ", cos_ave
   write(*,*)

 end subroutine non_planarity_check


!********************************************************************************
!* Statistics for tetra grid.
!*
!********************************************************************************

!*******************************************************************************
 subroutine tet_statistics(filename)

 character(80), intent(in) :: filename

 integer(kd), allocatable, dimension(:)   :: n_n2tet
 integer(kd), allocatable, dimension(:,:) :: n2tet
 integer(kd), allocatable, dimension(:,:) :: n2tet_k
 
 integer(kd)                              :: nedges
 integer(kd), allocatable, dimension(:,:) :: edge

 integer(kd)                              :: nfaces_i, nfaces_b, nfaces
 integer(kd), allocatable, dimension(:,:) :: face

 integer(kd), allocatable, dimension(:)   :: nc_nnghbrs
 integer(kd), allocatable, dimension(:,:) :: nc_nghbr
 integer(kd), allocatable, dimension(:)   :: nc_nnghbrs2
 integer(kd), allocatable, dimension(:,:) :: nc_nghbr2

 integer(kd), allocatable, dimension(:)   :: tet_nnghbrs
 integer(kd), allocatable, dimension(:,:) :: tet_nghbr
 integer(kd), allocatable, dimension(:)   :: tet_nnghbrs2
 integer(kd), allocatable, dimension(:,:) :: tet_nghbr2

 integer(kd) :: i, j, k, m, kv
 integer(kd) :: n1, n2
 integer(kd), dimension(4,3) :: nghbr

 integer(kd), allocatable, dimension(:)   :: bmark
 integer(kd), allocatable, dimension(:)   :: bmark_tet

 logical :: found
 integer(kd) :: itet
 integer(kd) :: v1, v2, v3, v4
 integer(kd) :: euler_residual

 character(80) :: temp_char

 open(unit=77, file=filename, status="unknown", iostat=os)

  write(77,*)
  write(77,*)
  write(77,*) "*********************************************************"
  write(77,*) "*********************************************************"
  write(77,*) "*********************************************************"
  write(77,*) " Some statistics for a tetra grid"
  write(77,*) "*********************************************************"
  write(77,*) "*********************************************************"
  write(77,*) "*********************************************************"
  write(77,*)

 !Neighbor nodes within a tetrahedron.

  nghbr(1,1) = 2
  nghbr(1,2) = 3
  nghbr(1,3) = 4

  nghbr(2,1) = 1
  nghbr(2,2) = 4
  nghbr(2,3) = 3

  nghbr(3,1) = 1
  nghbr(3,2) = 2
  nghbr(3,3) = 4

  nghbr(4,1) = 1
  nghbr(4,2) = 3
  nghbr(4,3) = 2

!--------------------------------------------------------------
!--------------------------------------------------------------
! Boundary mark: 0 for interior, 1 for boundary
!--------------------------------------------------------------
!--------------------------------------------------------------

  write(77,*) "*********************************************************"
  write(77,*) " Constructing bmark..."
  write(77,*)

  allocate(bmark(nnodes))
  bmark = 0

  do i = 1, ntrias_b
   do k = 1, 3
    bmark( tri(i,k) )  = -1
   end do
  end do

  do i = 1, nquads_b
   do k = 1, 4
    bmark( quad(i,k) ) = -1
   end do
  end do

!--------------------------------------------------------------
!--------------------------------------------------------------
! List of tets around each node.
!--------------------------------------------------------------
!--------------------------------------------------------------

  write(77,*) "*********************************************************"
  write(77,*) " Constructing a list of tets around each node..."
  write(77,*) " - Tetrahedral elements sharing the same node."
  write(77,*)

  allocate( n_n2tet(nnodes)  )

! Count the number of tetrahedra sharing the same node:
    n_n2tet = 0
  do i = 1, ntet
   do k = 1, 4
    n_n2tet( tet(i,k) ) = n_n2tet( tet(i,k) ) + 1 !# of tets around the node tet(i,k).
   end do
  end do

! (TBI) Add the number of prismatic elements.

! (TBI) Add the number of hexahedral  elements.


! Allocate the array to store the neighboring elments at each node.
! Use the maximum n_node2tet.

  allocate( n2tet  (nnodes, maxval(n_n2tet) ) )
  allocate( n2tet_k(nnodes, maxval(n_n2tet) ) )

! Construct the list of elements around each node.

  n_n2tet = 0

  do i = 1, ntet
   do k = 1, 4
    n_n2tet( tet(i,k) ) = n_n2tet( tet(i,k) ) + 1   !# of tets around the node tet(i,k).
      n2tet( tet(i,k)   , n_n2tet( tet(i,k) ) ) = i !Add tet i to the node tet(i,k).
    n2tet_k( tet(i,k)   , n_n2tet( tet(i,k) ) ) = k !Which vertex.
   end do
  end do

 !-------------------------------------------------
 ! Compute and display the data:
 !-------------------------------------------------

   temp_char= "Tets around node"
   call histogram(temp_char,nnodes,n_n2tet,bmark,-100000)

   temp_char= "Tets around node (interior)"
   call histogram(temp_char,nnodes,n_n2tet,bmark,-1)

   temp_char= "Tets around node (boundary)"
   call histogram(temp_char,nnodes,n_n2tet,bmark,0)

!--------------------------------------------------------------
!--------------------------------------------------------------
! List of nodes around each node.
!--------------------------------------------------------------
!--------------------------------------------------------------

  write(77,*) "*********************************************************"
  write(77,*) " Constructing a list of nodes around each node..."
  write(77,*) " - Edge-connected neighbor nodes for each node."
  write(77,*)

! real(dp) :: ave_n2tet, min_nc_nghbr, max_nc_nghbr
! allocate(hist_nc_nghbr)

  allocate( nc_nnghbrs(nnodes) )
  nc_nnghbrs = 0
  allocate( nc_nghbr(nnodes, maxval(n_n2tet) ) )

 !-------------------------------------------------
 ! Find edge-connected neghbr nodes from tets.
  do i = 1, ntet

  !-------------------------------------------------
  ! Loop over the vertices.
   do k = 1, 4

     n1 = tet(i,k)
     
   !-------------------------------------------------
   ! Loop over the rest of vertices.
    do j = 1, 3
     n2 = tet(i,nghbr(k,j))

     if ( nc_nnghbrs(n1) == 0 ) then

      nc_nnghbrs(n1) = 1
      nc_nghbr(n1,1) = n2

     else

     !Check if the neighbor is already added.
      found = .false.
      do m = 1, nc_nnghbrs(n1)
       if (n2 == nc_nghbr(n1,m)) then
        found = .true.
        exit
       endif
      end do

     !If not added yet, add it to the list.
      if (.not.found) then
       nc_nnghbrs(n1) = nc_nnghbrs(n1) + 1
       nc_nghbr(n1,nc_nnghbrs(n1)) = n2
      endif

     endif

    end do
   !-------------------------------------------------
   ! End of Loop over the rest of vertices.

   end do
  !-------------------------------------------------
  ! End of Loop over the vertices.

  end do
 ! End of Find edge-connected neghbr nodes from tets.
 !-------------------------------------------------
 
 !-------------------------------------------------
 ! (TBI) Find edge-connected neghbr nodes from prism.

 !-------------------------------------------------
 ! (TBI) Find edge-connected neghbr nodes from hexa.

 !-------------------------------------------------
 ! Compute and display the data:
 !-------------------------------------------------

   temp_char= "Node neighbors"
   call histogram(temp_char,nnodes,nc_nnghbrs,bmark,-100000)

   temp_char= "Node neighbors (interior)"
   call histogram(temp_char,nnodes,nc_nnghbrs,bmark,-1)

   temp_char= "Node neighbors (boundary)"
   call histogram(temp_char,nnodes,nc_nnghbrs,bmark,0)

!--------------------------------------------------------------
!--------------------------------------------------------------
! List of level2-nodes around each node.
!--------------------------------------------------------------
!--------------------------------------------------------------

  write(77,*) "*********************************************************"
  write(77,*) " Constructing a list of lvl2-nodes around each node..."
  write(77,*) " - Edge-connected neighbors and their neighbors."
  write(77,*)

  allocate( nc_nnghbrs2(nnodes) )
  nc_nnghbrs2 = 0
  allocate( nc_nghbr2(nnodes, 10*maxval(n_n2tet) ) )

 !-------------------------------------------------
  do i = 1, nnodes

  !Begin with the edge-connected neighbors.
    nc_nnghbrs2(i) = nc_nnghbrs(i)
   do k = 1, nc_nnghbrs(i)
    nc_nghbr2(i,k) = nc_nghbr(i,k)
   end do

  !-------------------------------------------------
  ! Loop over the neighbors
   do k = 1, nc_nnghbrs(i)

     n1 = nc_nghbr(i,k)
     
   !-------------------------------------------------
   ! Loop over the neighbors of the neighbor.
    do j = 1, nc_nnghbrs(n1)
     n2 = nc_nghbr(n1,k)

     !Check if the neighbor is already added.
      found = .false.
      do m = 1, nc_nnghbrs2(i)
       if (n2 == nc_nghbr2(i,m) .or. n2 == i) then
        found = .true.
        exit
       endif
      end do

     !If not added yet, add it to the list.
      if (.not.found) then
       nc_nnghbrs2(i) = nc_nnghbrs2(i) + 1
       nc_nghbr2(i,nc_nnghbrs2(i)) = n2
      endif

    end do
   !-------------------------------------------------

   end do
  !-------------------------------------------------

  end do
 !-------------------------------------------------

 !-------------------------------------------------
 ! Compute and display the data:
 !-------------------------------------------------

   temp_char= "Level2 node-nghbrs"
   call histogram(temp_char,nnodes,nc_nnghbrs2,bmark,-100000)

   temp_char= "Level2 node-nghbrs (interior)"
   call histogram(temp_char,nnodes,nc_nnghbrs2,bmark,-1)

   temp_char= "Level2 node-nghbrs (boundary)"
   call histogram(temp_char,nnodes,nc_nnghbrs2,bmark,0)

!--------------------------------------------------------------
!--------------------------------------------------------------
! Edge list
!--------------------------------------------------------------
!--------------------------------------------------------------

  write(77,*) "*********************************************************"
  write(77,*) " Constructing a list of edges..."
  write(77,*)

 !---------------------------------------
 ! First, count the number of edges.

  nedges = 0
  do i = 1, nnodes
   do k = 1, nc_nnghbrs(i)
    if ( i < nc_nghbr(i,k) ) then
      nedges = nedges + 1
    endif
   end do
  end do

 !---------------------------------------
 ! Allocate and fill edge array.

  allocate(edge(nedges,2))

  nedges = 0
  do i = 1, nnodes
   do k = 1, nc_nnghbrs(i)
    if ( i < nc_nghbr(i,k) ) then
      nedges = nedges + 1
      edge(nedges,1) = i
      edge(nedges,2) = nc_nghbr(i,k)
    endif
   end do
  end do

 !-------------------------------------------------
 ! Compute and display the data:
 !-------------------------------------------------

  write(77,*) " Number of edges = ", nedges
  write(77,*)
  write(77,*) " P2 element nodes = ", nnodes, "+", nedges, "=", nnodes + nedges
  write(77,*)

!--------------------------------------------------------------
!--------------------------------------------------------------
! Construct tet neighbor list.
!--------------------------------------------------------------
!--------------------------------------------------------------

  write(77,*) "*********************************************************"
  write(77,*) " Constructing a list of tet neighbors..."
  write(77,*) " - Face-neighbors of each tetrahedral element."
  write(77,*)

  allocate(tet_nnghbrs(ntet))
  tet_nnghbrs = 0
  allocate(tet_nghbr(ntet,4))

  do i = 1, ntet

   !--------------------------------------------------------
   ! Face 123
   !--------------------------------------------------------
    v1 = tet(i,1)
    v2 = tet(i,2)
    v3 = tet(i,3)
    v4 = 4

    found = .false.

    do k = 1, n_n2tet( v1    )

     itet = n2tet(     v1, k )
       kv = n2tet_k(   v1, k )

     if ( tet(itet,kv) /= v1 ) then 
      write(77,*) " Error in the surrounding tets..."
      stop
     endif

     if     ( tet(itet, nghbr(kv,2)) == v2 .and. tet(itet, nghbr(kv,1) ) == v3 ) then

                found = .true.
      tet_nnghbrs(i)  = tet_nnghbrs(i) + 1
      tet_nghbr(i,v4) = itet

     elseif ( tet(itet, nghbr(kv,3)) == v2 .and. tet(itet, nghbr(kv,2) ) == v3 ) then

                found = .true.
      tet_nnghbrs(i)  = tet_nnghbrs(i) + 1
      tet_nghbr(i,v4) = itet

     elseif ( tet(itet, nghbr(kv,1)) == v2 .and. tet(itet, nghbr(kv,3) ) == v3 ) then

                found = .true.
      tet_nnghbrs(i)  = tet_nnghbrs(i) + 1
      tet_nghbr(i,v4) = itet

     endif

     if (found) exit

    end do

    !--------------------------------------------------------
    !If not found, this must be a boundary face. Assign -1.
     if (.not.found) then
      tet_nghbr(i,v4) = -1
     endif

   !--------------------------------------------------------
   ! Face 141
   !--------------------------------------------------------
    v1 = tet(i,1)
    v2 = tet(i,4)
    v3 = tet(i,2)
    v4 = 3

    found = .false.

    do k = 1, n_n2tet( v1    )

     itet = n2tet(     v1, k )
       kv = n2tet_k(   v1, k )

     if ( tet(itet,kv) /= v1 ) then 
      write(77,*) " Error in the surrounding tets..."
      stop
     endif

     if     ( tet(itet, nghbr(kv,2)) == v2 .and. tet(itet, nghbr(kv,1) ) == v3 ) then

                found = .true.
      tet_nnghbrs(i)  = tet_nnghbrs(i) + 1
      tet_nghbr(i,v4) = itet

     elseif ( tet(itet, nghbr(kv,3)) == v2 .and. tet(itet, nghbr(kv,2) ) == v3 ) then

                found = .true.
      tet_nnghbrs(i)  = tet_nnghbrs(i) + 1
      tet_nghbr(i,v4) = itet

     elseif ( tet(itet, nghbr(kv,1)) == v2 .and. tet(itet, nghbr(kv,3) ) == v3 ) then

                found = .true.
      tet_nnghbrs(i)  = tet_nnghbrs(i) + 1
      tet_nghbr(i,v4) = itet

     endif

     if (found) exit

    end do

    !--------------------------------------------------------
    !If not found, this must be a boudnary face. Assign -1.
     if (.not.found) then
      tet_nghbr(i,v4) = -1
     endif

   !--------------------------------------------------------
   ! Face 134
   !--------------------------------------------------------
    v1 = tet(i,1)
    v2 = tet(i,3)
    v3 = tet(i,4)
    v4 = 2

    found = .false.

    do k = 1, n_n2tet( v1    )

     itet = n2tet(     v1, k )
       kv = n2tet_k(   v1, k )

     if ( tet(itet,kv) /= v1 ) then 
      write(77,*) " Error in the surrounding tets..."
      stop
     endif

     if     ( tet(itet, nghbr(kv,2)) == v2 .and. tet(itet, nghbr(kv,1) ) == v3 ) then

                found = .true.
      tet_nnghbrs(i)  = tet_nnghbrs(i) + 1
      tet_nghbr(i,v4) = itet

     elseif ( tet(itet, nghbr(kv,3)) == v2 .and. tet(itet, nghbr(kv,2) ) == v3 ) then

                found = .true.
      tet_nnghbrs(i)  = tet_nnghbrs(i) + 1
      tet_nghbr(i,v4) = itet

     elseif ( tet(itet, nghbr(kv,1)) == v2 .and. tet(itet, nghbr(kv,3) ) == v3 ) then

                found = .true.
      tet_nnghbrs(i)  = tet_nnghbrs(i) + 1
      tet_nghbr(i,v4) = itet

     endif

     if (found) exit

    end do

    !--------------------------------------------------------
    !If not found, this must be a boudnary face. Assign -1.
     if (.not.found) then
      tet_nghbr(i,v4) = -1
     endif

   !--------------------------------------------------------
   ! Face 243
   !--------------------------------------------------------
    v1 = tet(i,2)
    v2 = tet(i,4)
    v3 = tet(i,3)
    v4 = 1

    found = .false.

    do k = 1, n_n2tet( v1    )

     itet = n2tet(     v1, k )
       kv = n2tet_k(   v1, k )

     if ( tet(itet,kv) /= v1 ) then 
      write(77,*) " Error in the surrounding tets..."
      stop
     endif

     if     ( tet(itet, nghbr(kv,2)) == v2 .and. tet(itet, nghbr(kv,1) ) == v3 ) then

                found = .true.
      tet_nnghbrs(i)  = tet_nnghbrs(i) + 1
      tet_nghbr(i,v4) = itet

     elseif ( tet(itet, nghbr(kv,3)) == v2 .and. tet(itet, nghbr(kv,2) ) == v3 ) then

                found = .true.
      tet_nnghbrs(i)  = tet_nnghbrs(i) + 1
      tet_nghbr(i,v4) = itet

     elseif ( tet(itet, nghbr(kv,1)) == v2 .and. tet(itet, nghbr(kv,3) ) == v3 ) then

                found = .true.
      tet_nnghbrs(i)  = tet_nnghbrs(i) + 1
      tet_nghbr(i,v4) = itet

     endif

     if (found) exit

    end do

    !--------------------------------------------------------
    !If not found, this must be a boudnary face. Assign -1.
     if (.not.found) then
      tet_nghbr(i,v4) = -1
     endif

  end do


  allocate(bmark_tet(ntet))
  bmark_tet = 0

  do i = 1, ntet
   if ( minval(tet_nghbr(i,:)) == -1 ) then
    bmark_tet( i ) = -1
   endif
  end do

 !-------------------------------------------------
 ! Compute and display the data:
 !-------------------------------------------------

   temp_char= "cc-Tet-nghbrs"
   call histogram(temp_char,ntet,tet_nnghbrs,bmark_tet,-100000)

   temp_char= "cc-Tet-nghbrs (interior)"
   call histogram(temp_char,ntet,tet_nnghbrs,bmark_tet,-1)

   temp_char= "cc-Tet-nghbrs (boundary)"
   call histogram(temp_char,ntet,tet_nnghbrs,bmark_tet,0)


!--------------------------------------------------------------
!--------------------------------------------------------------
! Construct lvl2-tet neighbor list.
!--------------------------------------------------------------
!--------------------------------------------------------------

  write(77,*) "*********************************************************"
  write(77,*) " Constructing a list of lvl2-tet neighbors..."
  write(77,*) " - Face-neighbors and their neighbors."
  write(77,*)

  allocate(tet_nnghbrs2(ntet))
  tet_nnghbrs2 = 0
  allocate(tet_nghbr2(ntet,50))

 !Loop over tets
  do i = 1, ntet

    tet_nnghbrs2(i) = tet_nnghbrs(i)
   do k = 1, 4
    tet_nghbr2(i,k) = tet_nghbr(i,k)
   end do

  !Loop over tet neighbors
   do k = 1, tet_nnghbrs(i)
    n1 = tet_nghbr(i,k)
    if (n1 < 0) cycle

   !Loop over tet neighbors of the tet neighbors
    do j = 1, tet_nnghbrs(n1)
    n2 = tet_nghbr(n1,j)
    if (n2 < 0) cycle

     !Check if the neighbor is already added.
      found = .false.
      do m = 1, tet_nnghbrs2(i)
       if (n2 == tet_nghbr2(i,m) .or. n2 == i) then
        found = .true.
        exit
       endif
      end do

     !If not added yet, add it to the list.
      if (.not.found) then
       tet_nnghbrs2(i) = tet_nnghbrs2(i) + 1
       tet_nghbr2(i,tet_nnghbrs2(i)) = n2
      endif

    end do

   end do

  end do


 !-------------------------------------------------
 ! Compute and display the data:
 !-------------------------------------------------

   temp_char= "Level2 cc-tet-nghbrs"
   call histogram(temp_char,ntet,tet_nnghbrs2,bmark_tet,-100000)

   temp_char= "Level2 cc-tet-nghbrs (interior)"
   call histogram(temp_char,ntet,tet_nnghbrs2,bmark_tet,-1)

   temp_char= "Level2 cc-tet-nghbrs (boundary)"
   call histogram(temp_char,ntet,tet_nnghbrs2,bmark_tet,0)


!--------------------------------------------------------------
!--------------------------------------------------------------
! Construct face list.
!--------------------------------------------------------------
!--------------------------------------------------------------

  write(77,*) "*********************************************************"
  write(77,*) " Constructing a list of faces..."
  write(77,*)

  nfaces_i = 0
  nfaces_b = 0

  do i = 1, ntet
   do k = 1, 4
    if ( tet_nghbr(i,k) > 0 ) then
     if ( i < tet_nghbr(i,k) ) nfaces_i = nfaces_i + 1
    else
     nfaces_b = nfaces_b + 1
    endif
   end do
  end do

   nfaces = nfaces_i + nfaces_b

  allocate( face(nfaces,2) )

  nfaces = 0

 !Loop over tets
  do i = 1, ntet

  !Loop over tet neighbors
   do k = 1, 4
    n1 = tet_nghbr(i,k)

    if ( i < n1 ) then
     nfaces = nfaces + 1
     face(nfaces,1) = i
     face(nfaces,2) = n1
    endif

    if (n1 < 0) then
     nfaces = nfaces + 1
     face(nfaces,1) = i
     face(nfaces,2) = n1
    endif

   end do

  end do

  write(77,*) " Number of interior faces = ", nfaces_i
  write(77,*) " Number of boundary faces = ", nfaces_b
  write(77,*) " ---------------------------------------"
  write(77,*) " Number of    total faces = ", nfaces, nfaces_i+nfaces_b
  write(77,*)


!--------------------------------------------------------------
!--------------------------------------------------------------
! Check with Euler's formula: nnodes-nedges+nfaces+ncells=0.
!--------------------------------------------------------------
!--------------------------------------------------------------

  write(77,*) "*********************************************************"
  write(77,*) " Factors:"
  write(77,*)
  write(77,*) "   nnodes = ", nnodes
  write(77,*) "     ntet = ", ntet  , ": /nnodes = ", real  (ntet,dp)/real(nnodes,dp)
  write(77,*) "   nedges = ", nedges, ": /nnodes = ", real(nedges,dp)/real(nnodes,dp)
  write(77,*) "   nfaces = ", nfaces, ": /nnodes = ", real(nfaces,dp)/real(nnodes,dp)
  write(77,*) " P2 nodes = ", nnodes+nedges, ": /nnodes = ", &
                real(nnodes+nedges,dp)/real(nnodes,dp)
  write(77,*)
  write(77,*)

!--------------------------------------------------------------
!--------------------------------------------------------------
! Check with Euler's formula: nnodes-nedges+nfaces+ncells=0.
!--------------------------------------------------------------
!--------------------------------------------------------------

  write(77,*) "*********************************************************"
  write(77,*) " Check with Euler's formula: nnodes-nedges+nfaces-ncells=0,"
  write(77,*) " NOTE: ncells includes outside the domain: ncells <- ncells+1"
  write(77,*)
    euler_residual = nnodes - nedges + nfaces - (ntet + 1)
  write(77,*) "   Euler's formula (n-e+f-(c+1))  = ", euler_residual
  write(77,*)


  close(77)


 end subroutine tet_statistics
!*******************************************************************************
!*******************************************************************************
 subroutine histogram(dataname,ndata,data,flag,skip_value)
 implicit none

 character(80)                  , intent(in) :: dataname
 integer(kd),                   intent(in) :: ndata
 integer      ,                   intent(in) :: skip_value
 integer(kd), dimension(ndata), intent(in) :: data
 integer(kd), dimension(ndata), intent(in) :: flag

 real(dp) :: ave_q
 integer(kd)  :: min_q, max_q, ndata2
 integer(kd), dimension(:), allocatable :: hist_q
 
 ndata2 = 0
  ave_q =  0.0_dp
  min_q =  100000000
  max_q = -100000000

  write(77,*)
  write(77,*) " --------------------------------------------------------"
  write(77,*) " --------------------------------------------------------"
  write(77,'(10x,2a)') " Histogram for ", trim(dataname)
  write(77,*) " --------------------------------------------------------"
  write(77,*) " --------------------------------------------------------"

  do i = 1, ndata
   if (flag(i)==skip_value) cycle
   ndata2 = ndata2 + 1
    ave_q =     ave_q + real(data(i),dp)
    min_q = min(min_q,  data(i) )
    max_q = max(max_q,  data(i) )
  end do
    ave_q = ave_q / real(ndata2,dp)

  write(77,*) "  average = ", ave_q
  write(77,*) "  minimum = ", min_q
  write(77,*) "  maximum = ", max_q

  allocate( hist_q(max_q) )

   hist_q = 0
  do i = 1, ndata
   if (flag(i)==skip_value) cycle
   hist_q( data(i) ) = hist_q( data(i) ) + 1
  end do

   write(77,*) " --------------------------------------------------------"
   write(77,'(3x,2a)') trim(dataname),"   :  Occurence   "
  do k = 1, max_q
   if ( hist_q(k) == 0 ) cycle
   write(77,'(i20,a7,i10)') k, " : ", hist_q(k)
  end do
   write(77,*) " --------------------------------------------------------"

   write(77,*) " --------------------------------------------------------"
   write(77,*) " --------------------------------------------------------"
   write(77,*)

  deallocate( hist_q )

 end subroutine histogram
!*******************************************************************************


!*******************************************************************************
! This returns the element type of a f-grid cell:
!
! Input:
!
!   cell number: This is a number within a particular element type.
!
! Output:
!
!   cell number in a global array of cells.
!                The cells are ordered as tetra -> prisms -> hexa.
!
!*******************************************************************************
 function cell_number(icell)

 integer(kd), intent(in) :: icell
 integer(kd)             :: cell_number

 !-------------------------------------------------------------------------------
 !-------------------------------------------------------------------------------
 ! 'xxx_prism', 'xxx_mixed_ph', or 'xxx_strct'
 !-------------------------------------------------------------------------------
 !-------------------------------------------------------------------------------

  if (ntet == 0) then

   !---------------------------------
   ! 'xxx_prism'
   !---------------------------------

    if (nhex == 0) then

     cell_number = icell ! Prism
     return

   !---------------------------------
   ! 'xxx_mixed_ph', or 'xxx_strct'
   !---------------------------------

    else

     if (icell < nprs + 1) then


       cell_number = icell ! Prism
       return

     else

       cell_number = nhex + icell ! Hexa
       return

     endif

    endif

 !-------------------------------------------------------------------------------
 !-------------------------------------------------------------------------------
 ! 'xxx_tetra', 'xxx_mixed'
 !-------------------------------------------------------------------------------
 !-------------------------------------------------------------------------------

  else

     if (icell < ntet + 1) then

       cell_number = icell ! Tetra
       return

     else

       cell_number = ntet + icell ! Prism
       return

     endif

  endif
 !-------------------------------------------------------------------------------
 !-------------------------------------------------------------------------------
 !
 !-------------------------------------------------------------------------------
 !-------------------------------------------------------------------------------

 end function cell_number
!********************************************************************************


end program wing_grid
